style.css:
/* GIF en arrière-plan plein écran */
html, body {
    margin: 0 !important;
    padding: 0 !important;
    height: 100% !important;
    background: url("https://i.imgur.com/E4ubvfl.gif") no-repeat center center fixed !important;
    background-size: cover !important;
}

/* Optionnel : effet sombre par-dessus pour mieux voir le texte */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4); /* change 0.4 pour plus ou moins sombre */
    z-index: -1;
    pointer-events: none;
}
